/*
   Problem 4. On every switch press change the different LED pattern
 */

#include <stdio.h>
#include "led.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

int main(void)
{
	volatile uint8_t Num = 0;
	Init();
	Switch();

	while(1)
	{
		if(BV(0) & GPIOA -> IDR)
		{
			Led_Pattern(Num);
			DelayMs(500);
			Num++;
		}
		if(Num == 16)
		{
			Num = 0;
		}
	}

}
